using RentBuild.Platform.Rentals.Application.CommandServices;
using RentBuild.Platform.Rentals.Application.Internal.OutboundServices.Acl;
using RentBuild.Platform.Rentals.Domain.Model.Aggregates;
using RentBuild.Platform.Rentals.Domain.Model.Commands;
using RentBuild.Platform.Rentals.Domain.Model.ValueObjects;
using RentBuild.Platform.Rentals.Domain.Repositories;
using RentBuild.Platform.Shared.Application.Internal;
using RentBuild.Platform.Shared.Application.Model;
using RentBuild.Platform.Shared.Application.OutboundServices;
using RentBuild.Platform.Shared.Domain.Model.Errors;
using RentBuild.Platform.Shared.Domain.Model.ValueObjects;
namespace RentBuild.Platform.Rentals.Application.Internal.CommandServices;

public sealed class RentalCommandService(IRentalRequestRepository requests, IRentalRepository rentals, IDeliveryRepository deliveries, IEquipmentReturnRepository returns, IRentalInventory inventory, IRentalSubscriptions subscriptions, IRentalMaintenance maintenance, ICurrentActor actor, CommandExecutor executor) : IRentalCommandService
{
    async Task Available(int equipmentId, int owner, RentalPeriod period)
    {
        var e = await inventory.Find(equipmentId);
        Rule.Require(e.OwnerUserId == owner, "Equipment does not belong to the designated rental company");
        Rule.Require(await subscriptions.Active(owner), "Rental company needs an active subscription", ErrorKind.Conflict);
        Rule.Require(!await maintenance.BlockingIncident(equipmentId), "Equipment has an open blocking maintenance incident", ErrorKind.Conflict);
        Rule.Require(await inventory.Available(equipmentId, BusinessCalendar.Day(period.StartDate), BusinessCalendar.Day(period.EndDate)), "Equipment is unavailable for this period", ErrorKind.Conflict);
        Rule.Require(!(await rentals.ListAsync()).Any(r => r.EquipmentId == equipmentId && r.Status != RentalStatus.COMPLETED && r.Period.Overlaps(period)), "Equipment already has a confirmed or active rental for the selected period", ErrorKind.Conflict);
    }
    async Task Duplicate(int equipmentId, int constructor, RentalPeriod period, int? exclude = null) => Rule.Require(!(await requests.ListAsync()).Any(r => r.Id != exclude && r.EquipmentId == equipmentId && r.ConstructionUserId == constructor && r.Status != RentalRequestStatus.REJECTED && r.Period.Overlaps(period)), "You already have a pending or approved request for this equipment and an overlapping period", ErrorKind.Conflict);
    public Task<Result<RentalRequest>> Handle(SubmitRentalRequestCommand c) => executor.ExecuteAsync(async () => { actor.RequireRole("construction_company"); Rule.Owner(actor.UserId, c.ConstructionUserId); var period = new RentalPeriod(c.StartDate, c.EndDate); period.RequireNotPast(); await Available(c.EquipmentId, c.RentalCompanyUserId, period); await Duplicate(c.EquipmentId, c.ConstructionUserId, period); var request = new RentalRequest(c.EquipmentId, c.ConstructionUserId, c.RentalCompanyUserId, period); await requests.AddAsync(request); return request; });
    public Task<Result<RentalRequest>> Handle(RescheduleRentalRequestCommand c) => executor.ExecuteAsync(async () => { actor.RequireRole("construction_company"); var request = Rule.Found(await requests.FindByIdAsync(c.Id), "Rental request"); Rule.Owner(actor.UserId, request.ConstructionUserId); Rule.Require(request.Status == RentalRequestStatus.PENDING, "Only pending requests can be rescheduled", ErrorKind.Conflict); var period = new RentalPeriod(c.StartDate, c.EndDate); period.RequireNotPast(); await Available(request.EquipmentId, request.RentalCompanyUserId, period); await Duplicate(request.EquipmentId, request.ConstructionUserId, period, request.Id); request.Reschedule(period); return request; });
    public Task<Result<RentalRequest>> Handle(DecideRentalRequestCommand c) => executor.ExecuteAsync(async () => { actor.RequireRole("rental_company"); var request = Rule.Found(await requests.FindByIdAsync(c.Id), "Rental request"); Rule.Owner(actor.UserId, request.RentalCompanyUserId); Rule.Require(await subscriptions.Active(actor.UserId, 2), "Professional or Growth plan required", ErrorKind.Forbidden); if (c.Status == RentalRequestStatus.APPROVED) { await Available(request.EquipmentId, request.RentalCompanyUserId, request.Period); request.Period.RequireNotPast(); } request.Decide(c.Status); if (c.Status == RentalRequestStatus.APPROVED) { int block = await inventory.Reserve(request.EquipmentId, BusinessCalendar.Day(request.Period.StartDate), BusinessCalendar.Day(request.Period.EndDate)); await rentals.AddAsync(new Rental(request, block)); } return request; });
    public Task<Result<Delivery>> Handle(RegisterDeliveryCommand c) => executor.ExecuteAsync(async () => { actor.RequireRole("rental_company"); var rental = Rule.Found(await rentals.FindByIdAsync(c.RentalId), "Rental"); Rule.Owner(actor.UserId, rental.RentalCompanyUserId); Rule.Require(await subscriptions.Active(actor.UserId, 2), "Professional or Growth plan required", ErrorKind.Forbidden); Rule.Require(!await maintenance.BlockingIncident(rental.EquipmentId), "Equipment has an open blocking maintenance incident", ErrorKind.Conflict); Rule.Require(!(await deliveries.ListAsync()).Any(d => d.RentalId == rental.Id), "Delivery already registered", ErrorKind.Conflict); rental.Deliver(c.DeliveredAt, DateTimeOffset.UtcNow); await inventory.Deliver(rental.EquipmentId); var delivery = new Delivery(rental.Id, c.DeliveredAt, c.Notes ?? ""); await deliveries.AddAsync(delivery); return delivery; });
    public Task<Result<EquipmentReturn>> Handle(RegisterReturnCommand c) => executor.ExecuteAsync(async () => { actor.RequireRole("rental_company"); var rental = Rule.Found(await rentals.FindByIdAsync(c.RentalId), "Rental"); Rule.Owner(actor.UserId, rental.RentalCompanyUserId); var delivery = Rule.Found((await deliveries.ListAsync()).FirstOrDefault(d => d.RentalId == rental.Id), "Delivery"); Rule.Require(!(await returns.ListAsync()).Any(r => r.RentalId == rental.Id), "Return already registered", ErrorKind.Conflict); rental.Return(c.ReturnedAt, delivery.DeliveredAt, DateTimeOffset.UtcNow); bool restricted = c.MaintenanceRequired || await maintenance.BlockingIncident(rental.EquipmentId); await inventory.Return(rental.EquipmentId, rental.AvailabilityBlockId, restricted); if (c.MaintenanceRequired) await maintenance.ScheduleReturnWork(rental.EquipmentId, rental.RentalCompanyUserId); var record = new EquipmentReturn(rental.Id, c.ReturnedAt, c.Notes ?? "", c.MaintenanceRequired); await returns.AddAsync(record); return record; });
}
